package com.backend.nutri_predic.plandia.controller; import com.backend.nutri_predic.common.service.AccessService; import com.backend.nutri_predic.plandia.dto.*; import com.backend.nutri_predic.plandia.service.PlanDiarioService; import java.time.LocalDate; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/clientes/{clienteId}") public class PlanDiarioController {private final AccessService access;private final PlanDiarioService service;public PlanDiarioController(AccessService a,PlanDiarioService s){access=a;service=s;}@GetMapping("/plan-diario") public PlanDiarioResponse plan(@PathVariable Long clienteId,@RequestParam LocalDate fecha,Authentication a){access.client(clienteId,a);return service.plan(clienteId,fecha);}@GetMapping("/plan-diario/siguiente") public PlanDiarioResponse siguiente(@PathVariable Long clienteId,@RequestParam LocalDate fechaCorte,Authentication a){access.client(clienteId,a);return service.plan(clienteId,fechaCorte.plusDays(1));}@GetMapping("/cumplimiento-diario") public CumplimientoDiarioResponse cumplimiento(@PathVariable Long clienteId,@RequestParam LocalDate fecha,Authentication a){access.client(clienteId,a);return service.cumplimiento(clienteId,fecha);}@GetMapping("/planes-diarios") public java.util.List<PlanDiarioResponse> historialPlanes(@PathVariable Long clienteId,@RequestParam LocalDate desde,@RequestParam LocalDate hasta,Authentication a){access.client(clienteId,a);return service.historialPlanes(clienteId,desde,hasta);}@GetMapping("/cumplimientos-diarios") public java.util.List<CumplimientoDiarioResponse> historialCumplimientos(@PathVariable Long clienteId,@RequestParam LocalDate desde,@RequestParam LocalDate hasta,Authentication a){access.client(clienteId,a);return service.historialCumplimientos(clienteId,desde,hasta);}}
